","* { margin: 0; padding: 0; box-sizing: border-box; }

body {
 background: #060a18;
 color: #c0c8e4;
 font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.trend-app {
 max-width: 1100px;
 margin: 0 auto;
 padding: 32px 24px;
}

.trend-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 32px;
}

.trend-header h1 {
 font-size: 24px;
 font-weight: 700;
 color: #fff;
}

.trend-header h1 span {
 color: #aa00ff;
}

.trend-back-btn {
 padding: 8px 18px;
 border: 2px solid #4488ff;
 border-radius: 6px;
 background: rgba(68, 136, 255, 0.1);
 color: #82b1ff;
 font-size: 13px;
 font-weight: 700;
 cursor: pointer;
 transition: all 0.2s;
}

.trend-back-btn:hover {
 background: #4488ff;
 color: #fff;
 box-shadow: 0 0 16px rgba(68, 136, 255, 0.4);
}

.trend-chart-wrap {
 background: #0d1230;
 border: 1px solid #2a3060;
 border-radius: 10px;
 padding: 24px;
 margin-bottom: 32px;
}

.trend-chart-wrap h2 {
 font-size: 14px;
 font-weight: 700;
 color: #fff;
 margin-bottom: 16px;
}

.trend-chart-wrap svg {
 width: 100%;
 display: block;
}

.trend-tooltip {
 position: absolute;
 padding: 6px 12px;
 background: #1a1f45;
 border: 1px solid #4488ff;
 border-radius: 6px;
 font-size: 12px;
 color: #fff;
 pointer-events: none;
 white-space: nowrap;
 z-index: 100;
}

.trend-table-wrap {
 background: #0d1230;
 border: 1px solid #2a3060;
 border-radius: 10px;
 padding: 24px;
}

.trend-table-wrap h2 {
 font-size: 14px;
 font-weight: 700;
 color: #fff;
 margin-bottom: 16px;
}

.trend-table {
 width: 100%;
 border-collapse: collapse;
}

.trend-table th {
 text-align: left;
 font-size: 10px;
 font-weight: 700;
 color: #6b7394;
 text-transform: uppercase;
 letter-spacing: 1px;
 padding: 8px 12px;
 border-bottom: 1px solid #2a3060;
}

.trend-table td {
 padding: 10px 12px;
 font-size: 13px;
 border-bottom: 1px solid #151a38;
}

.trend-table tr:hover td {
 background: rgba(68, 136, 255, 0.05);
}

.trend-score { font-weight: 700; }
.trend-score--good { color: #00e676; }
.trend-score--warn { color: #ffab00; }
.trend-score--bad { color: #ff5252; }

.trend-loading {
 text-align: center;
 padding: 60px 0;
 color: #6b7394;
 font-size: 14px;
}

.trend-empty {
 text-align: center;
 padding: 60px 0;
 color: #6b7394;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useEffect, useState, useRef } from 'react';
import './trend.css';

declare const window: Window & { g_ck: string };

interface Scan {
 sys_id: string;
 scan_date: string;
 overall_score: string;
 total_classes: string;
 populated_classes: string;
 risk_count: string;
 summary: string;
}

const MARGIN = { top: 20, right: 20, bottom: 30, left: 40 };
const SVG_HEIGHT = 300;

function scoreColor(s: number) {
 if (s >= 75) return '#00e676';
 if (s >= 50) return '#ffab00';
 return '#ff5252';
}

function scoreCls(s: number) {
 if (s >= 75) return 'trend-score trend-score--good';
 if (s >= 50) return 'trend-score trend-score--warn';
 return 'trend-score trend-score--bad';
}

export default function TrendApp() {
 const [scans, setScans] = useState<Scan[]>([]);
 const [loading, setLoading] = useState(true);
 const [hoverIdx, setHoverIdx] = useState<number | null>(null);
 const [tooltip, setTooltip] = useState<{ x: number; y: number } | null>(null);
 const svgRef = useRef<SVGSVGElement>(null);

 useEffect(() => {
 fetch(
 '/api/now/table/x_147805_csdmviz_scan_result?sysparm_query=ORDERBYscan_date&sysparm_fields=sys_id,scan_date,overall_score,total_classes,populated_classes,risk_count,summary&sysparm_display_value=true&sysparm_limit=90',
 { headers: { Accept: 'application/json', 'X-UserToken': window.g_ck } }
 )
 .then((r) => r.json())
 .then((d) => setScans(d.result || []))
 .catch(() => {})
 .finally(() => setLoading(false));
 }, []);

 function handleMouseMove(e: React.MouseEvent<SVGSVGElement>) {
 if (!svgRef.current || scans.length < 2) return;
 const rect = svgRef.current.getBoundingClientRect();
 const mx = e.clientX - rect.left;
 const chartW = rect.width - MARGIN.left - MARGIN.right;
 const pct = (mx - MARGIN.left) / chartW;
 const idx = Math.round(pct * (scans.length - 1));
 if (idx >= 0 && idx < scans.length) {
 setHoverIdx(idx);
 setTooltip({ x: e.clientX, y: e.clientY });
 }
 }

 function handleMouseLeave() {
 setHoverIdx(null);
 setTooltip(null);
 }

 function renderChart() {
 if (scans.length === 0) return <div className="trend-empty">No scan data yet.</div>;
 const scores = scans.map((s) => parseFloat(s.overall_score) || 0);
 const n = scores.length;
 const viewW = 800;
 const chartW = viewW - MARGIN.left - MARGIN.right;
 const chartH = SVG_HEIGHT - MARGIN.top - MARGIN.bottom;

 const x = (i: number) => MARGIN.left + (n === 1 ? chartW / 2 : (i / (n - 1)) * chartW);
 const y = (v: number) => MARGIN.top + chartH - (v / 100) * chartH;

 // Build path segments colored by score
 const segments: React.ReactNode[] = [];
 for (let i = 0; i < n - 1; i++) {
 segments.push(
 <line key={`seg${i}`} x1={x(i)} y1={y(scores[i])} x2={x(i + 1)} y2={y(scores[i + 1])}
 stroke={scoreColor(scores[i])} strokeWidth="2.5" strokeLinecap="round" />
 );
 }

 // Y-axis labels
 const yLabels = [0, 25, 50, 75, 100].map((v) => (
 <g key={`yl${v}`}>
 <text x={MARGIN.left - 6} y={y(v) + 4} textAnchor="end" fontSize="10" fill="#6b7394">{v}</text>
 <line x1={MARGIN.left} y1={y(v)} x2={viewW - MARGIN.right} y2={y(v)} stroke="#1a2040" strokeWidth="1" />
 </g>
 ));

 // X-axis labels (show ~6 evenly spaced)
 const xStep = Math.max(1, Math.floor(n / 6));
 const xLabels: React.ReactNode[] = [];
 for (let i = 0; i < n; i += xStep) {
 const d = scans[i].scan_date;
 const short = d.length >= 10 ? d.substring(5, 10) : d;
 xLabels.push(
 <text key={`xl${i}`} x={x(i)} y={SVG_HEIGHT - 4} textAnchor="middle" fontSize="10" fill="#6b7394">{short}</text>
 );
 }

 return (
 <svg ref={svgRef} viewBox={`0 0 ${viewW} ${SVG_HEIGHT}`} preserveAspectRatio="xMidYMid meet"
 onMouseMove={handleMouseMove} onMouseLeave={handleMouseLeave}>
 {yLabels}
 {/* Reference lines */}
 <line x1={MARGIN.left} y1={y(75)} x2={viewW - MARGIN.right} y2={y(75)}
 stroke="#00e676" strokeWidth="1" strokeDasharray="6 3" opacity="0.4" />
 <line x1={MARGIN.left} y1={y(50)} x2={viewW - MARGIN.right} y2={y(50)}
 stroke="#ffab00" strokeWidth="1" strokeDasharray="6 3" opacity="0.4" />
 {segments}
 {scores.map((v, i) => (
 <circle key={`pt${i}`} cx={x(i)} cy={y(v)} r={hoverIdx === i ? 5 : 3}
 fill={scoreColor(v)} stroke={hoverIdx === i ? '#fff' : 'none'} strokeWidth="2" />
 ))}
 {xLabels}
 </svg>
 );
 }

 if (loading) return <div className="trend-loading">Loading trend data…</div>;

 return (
 <div className="trend-app">
 <div className="trend-header">
 <h1>📈 CSDM <span>Trend Analysis</span></h1>
 <button className="trend-back-btn" onClick={() => window.open('/x_147805_csdmviz_explorer.do', '_self')}>
 ← Back to Explorer
 </button>
 </div>

 <div className="trend-chart-wrap" style={{ position: 'relative' }}>
 <h2>Overall Score Over Time</h2>
 {renderChart()}
 {hoverIdx !== null && tooltip && (
 <div className="trend-tooltip" style={{ left: tooltip.x + 12, top: tooltip.y - 36, position: 'fixed' }}>
 {scans[hoverIdx].scan_date} — <strong>{scans[hoverIdx].overall_score}%</strong>
 </div>
 )}
 </div>

 <div className="trend-table-wrap">
 <h2>Scan History ({scans.length} scans)</h2>
 {scans.length === 0 ? (
 <div className="trend-empty">No scan records found.</div>
 ) : (
 <table className="trend-table">
 <thead>
 <tr><th>Date</th><th>Score</th><th>Classes</th><th>Risks</th><th>Summary</th></tr>
 </thead>
 <tbody>
 {[...scans].reverse().map((s) => {
 const sc = parseFloat(s.overall_score) || 0;
 return (
 <tr key={s.sys_id}>
 <td>{s.scan_date}</td>
 <td className={scoreCls(sc)}>{sc}%</td>
 <td>{s.populated_classes}/{s.total_classes}</td>
 <td>{s.risk_count}</td>
 <td style={{ maxWidth: 300, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
 {s.summary}
 </td>
 </tr>
 );
 })}
 </tbody>
 </table>
 )}
 </div>
 </div>
 );
}
","import React from 'react';
import ReactDOM from 'react-dom/client';
import TrendApp from './TrendApp';

ReactDOM.createRoot(document.getElementById('root')!).render(<TrendApp />);
